/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.bs4;import java.util.List;import java.util.Map;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import page2020.core.App;import page2020.util.EmptyUtil;import page2020.view.C3;import page2020.view.H5;import page2020.view.Text;import page2020.view.Value;import page2020.view.css3.C3color.Grey;import page2020.view.html5.H5select;public class B4select extends H5select {	public static final String select = "custom-select";	public static final String sm = "custom-select-sm";	public static final String lg = "custom-select-lg";	private static final String tip = "tip";	private static Logger log = LoggerFactory.getLogger(B4select.class);	private Boolean disabled = Boolean.FALSE;	private Boolean multiple = Boolean.FALSE;	public B4select() {		super();		super.cssClass(select).append(			new B4option().cssClass(tip).css(C3.color(Grey.DarkGray)).value("")		);	}	public B4select sm() {		super.cssClass(sm);		return this;	}	public B4select lg() {		super.cssClass(lg);		return this;	}	public B4select items(String datalistKey) {		if (EmptyUtil.not(datalistKey)) {			Map<String, Object> items = App.itemValue(datalistKey);			if (items != null) {				items.forEach((key, value) -> super.append(					new B4option().value(key).disabled(this.disabled).append(						new Text().code(App.itemKey(datalistKey, key)))));			} else {				log.error("items: argument(" + datalistKey + ") is invalid !");			}		} else {			log.error("items: argument(datalistKey) has empty !");		}		return this;	}	public B4select items(String className, String fieldName) {		return this.items(className + "." + fieldName);	}	public B4select items(Class<?> clazz, String fieldName) {		return this.items(App.className(clazz) + "." + fieldName);	}	public B4select items(Map<String, ?> items) {		if (EmptyUtil.not(items)) {			items.forEach((key, value) -> super.append(				new B4option().disabled(this.disabled).value(key).append(					new Value().value(value))));		}		return this;	}	public B4select items(List<String> items) {		if (EmptyUtil.not(items)) {			items.forEach(item -> super.append(				new B4option().disabled(this.disabled).value(item).append(					new Value().value(item))));		}		return this;	}	public B4select itemsCode(Map<String, String> items) {		if (EmptyUtil.not(items)) {			items.forEach((key, code) -> super.append(new B4option().value(key).append(H5.code(code))));		}		return this;	}	@Override	public B4select value(Object value) {		boolean selected = false;		if (EmptyUtil.not(value) && super.count() > 1) {			int count = super.count();			for (int i=1; i < count; i++) {				B4option option = (B4option) super.get(i);				if (value.equals(option.getAttrMap().get(B4option.Attr.value))) {					option.selected(true);					selected = true;					break;				}			}		}		if (selected) {			((B4option) super.get(0)).selected(false);		}		return this;	}	public B4select value(List<?> values) {		boolean selected = false;		if (EmptyUtil.not(values) && super.count() > 1) {			int count = super.count();			for (Object value : values) {				for (int i=1; i < count; i++) {					B4option option = (B4option) super.get(i);					if (value.equals(option.getAttrMap().get(B4option.Attr.value))) {						option.selected(true);						selected = true;					}				}			}		}		if (selected) {			((B4option) super.get(0)).selected(false);		}		return this;	}	public B4select tip(String code) {		((B4option) super.get(0)).append(new Text().code(code));		return this;	}	public B4select clear() {		while (super.count() > 1) {			super.remove(super.count() - 1);		}		return this;	}	@Override	public B4select disabled(boolean disabled) {		this.disabled = disabled;		if (disabled) {			super.cssClass(B4ctrl.disabled);		} else {			super.removeClass(B4ctrl.disabled);		}		int count = super.count();		for (int i=0; i < count; i++) {			((B4option) super.get(i)).disabled(disabled);			}		return this;	}	@Override	public B4select multiple(boolean multiple) {		this.multiple = multiple;		super.multiple(multiple);		return this;	}	@Override	public B4select copy() {		return (B4select) super.copy();	}	public Boolean getDisabled() {		return disabled;	}	public void setDisabled(Boolean disabled) {		this.disabled = disabled;	}	public Boolean getMultiple() {		return multiple;	}	public void setMultiple(Boolean multiple) {		this.multiple = multiple;	}}